"""### 數據洩漏 (Data Leakage) 深度檢查
如果驗證集中的文字與訓練集中的文字高度重複（超過 90% 相似），那麼 1.0 的分數就不能代表真實性能。我們使用字元重合度來檢查。
"""

def calculate_similarity(s1, s2):
    # 簡單的字元集合相似度 (Jaccard Similarity)
    set1, set2 = set(s1), set(s2)
    return len(set1 & set2) / len(set1 | set2)

print("正在檢查驗證集是否洩漏自訓練集...")
leakage_count = 0
threshold = 0.85 # 相似度門檻

train_texts = [item['data'] for item in train_data]

for i, val_item in enumerate(val_data):
    v_text = val_item['data']
    # 檢查驗證集文字是否出現在訓練集中
    best_sim = 0
    for t_text in train_texts:
        # 先做快速長度過濾以加速
        if abs(len(t_text) - len(v_text)) > 50: continue
        sim = calculate_similarity(v_text, t_text)
        if sim > best_sim: best_sim = sim
        if sim > 0.98: break # 幾乎完全相同

    if best_sim > threshold:
        leakage_count += 1

leak_ratio = leakage_count / len(val_data)
print(f"\n檢查結果：")
print(f"  相似度超過 {threshold*100}% 的樣本數: {leakage_count} / {len(val_data)}")
print(f"  洩漏比例: {leak_ratio:.2%}")

if leak_ratio > 0.1:
    print("\n⚠️ 警告：偵測到嚴重的資料洩漏！驗證集有太多文字與訓練集重複 1.0。")
else:
    print("\n✅ 驗證集相對獨立。")

